import React, { useState, useEffect } from 'react';
import DriverDashboard from './DriverDashboard';

function Dashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [vehicles, setVehicles] = useState([]);
  const [services, setServices] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [myServices, setMyServices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showServiceForm, setShowServiceForm] = useState(false);
  const [newService, setNewService] = useState({ name: '', description: '', category: 'oil-change', price: '', duration: '' });

  const token = localStorage.getItem('token');

  const categories = [
    { id: 'oil-change', name: 'Oil Change', icon: '🛢️' },
    { id: 'brake-repair', name: 'Brake Repair', icon: '🛑' },
    { id: 'tire-service', name: 'Tire Service', icon: '🛞' },
    { id: 'engine-repair', name: 'Engine Repair', icon: '🔧' },
    { id: 'ac-repair', name: 'AC Repair', icon: '❄️' },
    { id: 'transmission', name: 'Transmission', icon: '⚙️' },
    { id: 'detailing', name: 'Detailing', icon: '🧼' },
    { id: 'maintenance', name: 'Maintenance', icon: '📋' }
  ];

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const serviceRes = await fetch('http://localhost:5000/api/services');
      const serviceData = await serviceRes.json();
      if (serviceData.success) setServices(serviceData.services);

      if (user?.role === 'customer') {
        const vehicleRes = await fetch('http://localhost:5000/api/services/customer/vehicles', {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        const vehicleData = await vehicleRes.json();
        if (vehicleData.success) setVehicles(vehicleData.vehicles);

        const bookingRes = await fetch('http://localhost:5000/api/services/customer/bookings', {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        const bookingData = await bookingRes.json();
        if (bookingData.success) setBookings(bookingData.bookings);
      }

      if (user?.role === 'provider') {
        const myServicesRes = await fetch('http://localhost:5000/api/services/provider/my-services', {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        const myServicesData = await myServicesRes.json();
        if (myServicesData.success) setMyServices(myServicesData.services);

        const providerBookingsRes = await fetch('http://localhost:5000/api/services/provider/bookings', {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        const providerBookingsData = await providerBookingsRes.json();
        if (providerBookingsData.success) setBookings(providerBookingsData.bookings);
      }
    } catch (error) {
      console.error('Error fetching data:', error);
    } finally {
      setLoading(false);
    }
  };

  const addService = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch('http://localhost:5000/api/services', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(newService)
      });
      const data = await res.json();
      if (data.success) {
        setMyServices([...myServices, data.service]);
        setShowServiceForm(false);
        setNewService({ name: '', description: '', category: 'oil-change', price: '', duration: '' });
        alert('Service added successfully!');
      }
    } catch (error) {
      alert('Failed to add service');
    }
  };

  const updateBookingStatus = async (bookingId, status) => {
    try {
      const res = await fetch(`http://localhost:5000/api/services/provider/bookings/${bookingId}/status`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ status })
      });
      const data = await res.json();
      if (data.success) {
        alert(`Booking ${status}!`);
        fetchData();
      }
    } catch (error) {
      alert('Failed to update booking');
    }
  };

  const getStatusBadge = (status) => {
    const colors = {
      pending: '#f59e0b',
      confirmed: '#10b981',
      'in-progress': '#3b82f6',
      completed: '#8b5cf6',
      cancelled: '#ef4444'
    };
    return { backgroundColor: colors[status] || '#6b7280', color: 'white', padding: '4px 12px', borderRadius: '20px', fontSize: '12px' };
  };

  // Driver Dashboard redirect
  if (user?.role === 'driver') {
    return <DriverDashboard user={user} onLogout={onLogout} />;
  }

  // Customer Dashboard
  if (user?.role === 'customer') {
    return (
      <div style={styles.dashboard}>
        <div style={styles.header}>
          <div style={styles.logoSection}>
            <span style={styles.logoIcon}>🚗💨</span>
            <h1 style={styles.logoText}>Car Care Connect</h1>
          </div>
          <div style={styles.userInfo}>
            <span>👤 {user.firstName} {user.lastName}</span>
            <button onClick={onLogout} style={styles.logoutButton}>Logout</button>
          </div>
        </div>

        <div style={styles.tabs}>
          <button style={{...styles.tab, ...(activeTab === 'dashboard' ? styles.activeTab : {})}} onClick={() => setActiveTab('dashboard')}>📊 Dashboard</button>
          <button style={{...styles.tab, ...(activeTab === 'services' ? styles.activeTab : {})}} onClick={() => setActiveTab('services')}>🔧 Services</button>
          <button style={{...styles.tab, ...(activeTab === 'vehicles' ? styles.activeTab : {})}} onClick={() => setActiveTab('vehicles')}>🚗 Vehicles</button>
          <button style={{...styles.tab, ...(activeTab === 'bookings' ? styles.activeTab : {})}} onClick={() => setActiveTab('bookings')}>📅 Bookings</button>
        </div>

        <div style={styles.content}>
          {loading ? <div style={styles.loading}>Loading...</div> : (
            <>
              {activeTab === 'dashboard' && (
                <div>
                  <div style={styles.statsGrid}>
                    <div style={styles.statCard}><h3>🚗 Vehicles</h3><p style={styles.statNumber}>{vehicles.length}</p></div>
                    <div style={styles.statCard}><h3>📅 Bookings</h3><p style={styles.statNumber}>{bookings.length}</p></div>
                    <div style={styles.statCard}><h3>✅ Completed</h3><p style={styles.statNumber}>{bookings.filter(b => b.status === 'completed').length}</p></div>
                  </div>
                  <div style={styles.card}>
                    <h3>Quick Actions</h3>
                    <div style={styles.quickActions}>
                      <button style={styles.quickActionBtn} onClick={() => setActiveTab('services')}>Book a Service →</button>
                      <button style={styles.quickActionBtn} onClick={() => setActiveTab('vehicles')}>Add Vehicle →</button>
                    </div>
                  </div>
                </div>
              )}

              {activeTab === 'services' && (
                <div>
                  <h2>🔧 Available Services</h2>
                  <div style={styles.servicesGrid}>
                    {services.map(service => (
                      <div key={service._id} style={styles.serviceCard}>
                        <h3>{service.name}</h3>
                        <p>{service.description}</p>
                        <p><strong>Price:</strong> ${service.price}</p>
                        <button style={styles.bookBtn} onClick={() => alert('Booking coming soon!')}>Book Now</button>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {activeTab === 'vehicles' && (
                <div>
                  <h2>🚗 My Vehicles</h2>
                  {vehicles.length === 0 ? <div style={styles.emptyState}>No vehicles added yet.</div> : 
                    vehicles.map(vehicle => (
                      <div key={vehicle._id} style={styles.vehicleCard}>
                        <strong>{vehicle.year} {vehicle.make} {vehicle.model}</strong> - {vehicle.licensePlate}
                      </div>
                    ))
                  }
                  <button style={styles.addBtn} onClick={() => alert('Add vehicle form coming soon')}>+ Add Vehicle</button>
                </div>
              )}

              {activeTab === 'bookings' && (
                <div>
                  <h2>📅 My Bookings</h2>
                  {bookings.length === 0 ? <div style={styles.emptyState}>No bookings yet.</div> :
                    bookings.map(booking => (
                      <div key={booking._id} style={styles.bookingCard}>
                        <div><h3>{booking.serviceName}</h3><span style={getStatusBadge(booking.status)}>{booking.status}</span></div>
                        <p>📅 {new Date(booking.bookingDate).toLocaleDateString()}</p>
                        <p>💰 ${booking.totalAmount}</p>
                      </div>
                    ))
                  }
                </div>
              )}
            </>
          )}
        </div>
      </div>
    );
  }

  // Provider Dashboard
  if (user?.role === 'provider') {
    return (
      <div style={styles.dashboard}>
        <div style={styles.header}>
          <div style={styles.logoSection}>
            <span style={styles.logoIcon}>🔧</span>
            <h1 style={styles.logoText}>Car Care Connect - Provider</h1>
          </div>
          <div style={styles.userInfo}>
            <span>🔧 {user.businessName || user.firstName}</span>
            <button onClick={onLogout} style={styles.logoutButton}>Logout</button>
          </div>
        </div>

        <div style={styles.tabs}>
          <button style={{...styles.tab, ...(activeTab === 'dashboard' ? styles.activeTab : {})}} onClick={() => setActiveTab('dashboard')}>📊 Dashboard</button>
          <button style={{...styles.tab, ...(activeTab === 'services' ? styles.activeTab : {})}} onClick={() => setActiveTab('services')}>🛠️ My Services</button>
          <button style={{...styles.tab, ...(activeTab === 'bookings' ? styles.activeTab : {})}} onClick={() => setActiveTab('bookings')}>📅 Bookings</button>
          <button style={{...styles.tab, ...(activeTab === 'earnings' ? styles.activeTab : {})}} onClick={() => setActiveTab('earnings')}>💰 Earnings</button>
        </div>

        <div style={styles.content}>
          {loading ? <div style={styles.loading}>Loading...</div> : (
            <>
              {activeTab === 'dashboard' && (
                <div>
                  <div style={styles.statsGrid}>
                    <div style={styles.statCard}><h3>🛠️ Services</h3><p style={styles.statNumber}>{myServices.length}</p></div>
                    <div style={styles.statCard}><h3>📅 Bookings</h3><p style={styles.statNumber}>{bookings.length}</p></div>
                    <div style={styles.statCard}><h3>💰 Revenue</h3><p style={styles.statNumber}>${bookings.filter(b => b.status === 'completed').reduce((sum, b) => sum + (b.totalAmount || 0), 0)}</p></div>
                  </div>
                  <button style={styles.quickActionBtn} onClick={() => setActiveTab('services')}>Add New Service →</button>
                </div>
              )}

              {activeTab === 'services' && (
                <div>
                  <button style={styles.addBtn} onClick={() => setShowServiceForm(!showServiceForm)}>+ Add Service</button>
                  {showServiceForm && (
                    <div style={styles.formCard}>
                      <form onSubmit={addService}>
                        <input style={styles.input} placeholder="Service Name" value={newService.name} onChange={(e) => setNewService({...newService, name: e.target.value})} required />
                        <textarea style={styles.textarea} placeholder="Description" value={newService.description} onChange={(e) => setNewService({...newService, description: e.target.value})} required />
                        <select style={styles.input} value={newService.category} onChange={(e) => setNewService({...newService, category: e.target.value})}>
                          {categories.map(cat => <option key={cat.id} value={cat.id}>{cat.icon} {cat.name}</option>)}
                        </select>
                        <input style={styles.input} type="number" placeholder="Price ($)" value={newService.price} onChange={(e) => setNewService({...newService, price: e.target.value})} required />
                        <input style={styles.input} type="number" placeholder="Duration (minutes)" value={newService.duration} onChange={(e) => setNewService({...newService, duration: e.target.value})} required />
                        <button style={styles.submitBtn} type="submit">Save</button>
                      </form>
                    </div>
                  )}
                  {myServices.map(service => (
                    <div key={service._id} style={styles.serviceCard}>
                      <h3>{service.name}</h3>
                      <p>${service.price} - {service.duration} min</p>
                    </div>
                  ))}
                </div>
              )}

              {activeTab === 'bookings' && (
                <div>
                  {bookings.map(booking => (
                    <div key={booking._id} style={styles.bookingCard}>
                      <h3>{booking.serviceName}</h3>
                      <p>Customer: {booking.customerId?.firstName}</p>
                      <p>Date: {new Date(booking.bookingDate).toLocaleDateString()}</p>
                      <span style={getStatusBadge(booking.status)}>{booking.status}</span>
                      {booking.status === 'pending' && (
                        <div><button onClick={() => updateBookingStatus(booking._id, 'confirmed')}>Confirm</button></div>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </>
          )}
        </div>
      </div>
    );
  }

  // Admin Dashboard
  return (
    <div style={styles.dashboard}>
      <div style={styles.header}>
        <div style={styles.logoSection}>
          <span style={styles.logoIcon}>👑</span>
          <h1 style={styles.logoText}>Car Care Connect - Admin</h1>
        </div>
        <div style={styles.userInfo}>
          <span>👑 {user.firstName} {user.lastName}</span>
          <button onClick={onLogout} style={styles.logoutButton}>Logout</button>
        </div>
      </div>
      <div style={styles.content}>
        <div style={styles.statsGrid}>
          <div style={styles.statCard}><h3>👥 Users</h3><p style={styles.statNumber}>0</p></div>
          <div style={styles.statCard}><h3>📅 Bookings</h3><p style={styles.statNumber}>{bookings.length}</p></div>
        </div>
        <div style={styles.card}><h3>Admin Dashboard</h3><p>Coming soon: User management, analytics, and platform controls.</p></div>
      </div>
    </div>
  );
}

