  tabs: { display: 'flex', backgroundColor: 'white', borderBottom: '1px solid #e5e7eb', padding: '0 20px', gap: '5px' },
  tab: { padding: '12px 24px', background: 'none', border: 'none', cursor: 'pointer', fontSize: '14px', fontWeight: '500' },
