  vehicleCard: { backgroundColor: 'white', padding: '15px', borderRadius: '10px', marginBottom: '10px' },
  bookingCard: { backgroundColor: 'white', padding: '15px', borderRadius: '10px', marginBottom: '10px' },
  formCard: { backgroundColor: 'white', padding: '20px', borderRadius: '10px', marginBottom: '20px' },
  input: { width: '100%', padding: '10px', marginBottom: '10px', border: '1px solid #d1d5db', borderRadius: '6px' },
  textarea: { width: '100%', padding: '10px', marginBottom: '10px', border: '1px solid #d1d5db', borderRadius: '6px', minHeight: '80px' },
  submitBtn: { backgroundColor: '#10b981', color: 'white', border: 'none', padding: '10px 20px', borderRadius: '6px', cursor: 'pointer' },
  emptyState: { textAlign: 'center', padding: '50px', color: '#6b7280' }
